#include "RaidWaveStateMachine.h"
void URaidWaveStateMachine::Initialize(int32 N){TotalWaves=FMath::Max(0,N);CurrentWaveIndex=0;CurrentState=TotalWaves>0?EWaveState::Preparation:EWaveState::Completed;WaveStartTime=IntermissionStartTime=0.f;}
void URaidWaveStateMachine::TransitionTo(EWaveState S){CurrentState=S;}
void URaidWaveStateMachine::Tick(float Now,int32 Remaining,int32 Live,float Duration){switch(CurrentState){case EWaveState::Preparation:WaveStartTime=Now;TransitionTo(EWaveState::Producing);break;case EWaveState::Producing:if(Remaining<=0||Now-WaveStartTime>=Duration)TransitionTo(EWaveState::ProductionClosed);break;case EWaveState::ProductionClosed:IntermissionStartTime=Now;TransitionTo(EWaveState::Intermission);break;case EWaveState::Intermission:if((Live<=0&&Now-IntermissionStartTime>=0.5f)||Now-IntermissionStartTime>=FMath::Max(0.f,IntermissionDuration)){if(CurrentWaveIndex+1<TotalWaves){++CurrentWaveIndex;TransitionTo(EWaveState::NextWave);}else TransitionTo(EWaveState::Completed);}break;case EWaveState::NextWave:WaveStartTime=Now;TransitionTo(EWaveState::Producing);break;case EWaveState::Completed:break;}}
